export const ACTION_GROUPS = ['Public data'];

const LIST_OUT = 'One item for each thing the app lists.';
const ONE_OUT = 'One item per input item: what the app answered (an id, a link, a status).';
const q = s => encodeURIComponent(String(s));
const strip = s => String(s || '').replace(/\/+$/, '');
const F = (k, label, hint, o = {}) => ({ k, label, kind: o.kind || 'text', ...(hint ? { hint } : {}), ...(o.options ? { options: o.options } : {}), ...(o.d !== undefined ? { d: o.d } : {}) });
const TA = (k, label, hint, o = {}) => F(k, label, hint, { ...o, kind: 'textarea' });
const NUM = (k, label, d) => F(k, label, '', { kind: 'number', d });
const SEL = (k, label, options, d) => F(k, label, '', { kind: 'select', options, d: d ?? options[0][0] });
const LIMIT = NUM('limit', 'At most', 20);
const lim = (p, d = 20, max = 100) => Math.min(max, Math.max(1, Number(p.limit) || d));
const list = v => (Array.isArray(v) ? v : String(v ?? '').split(',')).map(s => String(s).trim()).filter(Boolean);

function A(svc, key, label, note, fields, call, o = {}) {
  const s = SVC[svc], type = `${svc}.${key}`;
  const ex = o.ex || `${fields.filter(f => f.hint).slice(0, 3).map(f => `${f.label}: ${f.hint}`).join(' · ') || 'Pick the credential'} → ${o.list ? 'one item each' : 'the app’s answer'}`;
  ACTION_META[type] = {
    group: s.group, label: s.name ? `${s.name}: ${label}` : label, note, ...(s.logo ? { logo: s.logo } : {}), icon: o.icon || s.icon || 'plug', tone: s.tone,
    ...(s.cred ? { credential: [s.cred] } : {}),
    fields: fields.map(({ d, ...f }) => f),
    defaults: Object.fromEntries(fields.filter(f => f.d !== undefined).map(f => [f.k, f.d])),
    guide: { what: `${note}.`, ex, out: o.out || (o.list ? LIST_OUT : ONE_OUT) },
  };
  ACTION_NODES[type] = { run: async args => { const c = s.cred ? await cred(args) : null; return each(args, p => call(args, c, p)); } };
}

/* ================= GitHub ================= */
const REPO = F('repo', 'Repository', 'owner/name');
const NUMBER = F('number', 'Issue or PR number', '{{ $json.number }}');
const repo = p => { const r = String(need(p.repo, 'the repository (owner/name)')).trim().replace(/^https:\/\/github\.com\//, '').replace(/\.git$/, ''); if (!/^[\w.-]+\/[\w.-]+$/.test(r)) throw new FlowError('The repository is owner/name, e.g. octocat/hello-world.', 'bad_param'); return r; };
const gh = async (args, c, path, init = {}) => failIfBad(await api(args, `https://api.github.com${path}`, { ...init, bearer: c.token, headers: { accept: 'application/vnd.github+json', 'user-agent': 'Workline', 'x-github-api-version': '2022-11-28' } }), 'GitHub');
A('github', 'comment', 'Comment on an issue or PR', 'Adds a comment to an issue or pull request', [REPO, NUMBER, TA('body', 'Comment', 'Thanks! Looking into it.')], (a, c, p) => gh(a, c, `/repos/${repo(p)}/issues/${q(need(p.number, 'the number'))}/comments`, { method: 'POST', body: { body: need(p.body, 'the comment') } }).then(b => ({ id: b.id, url: b.html_url })));
A('github', 'closeIssue', 'Close an issue', 'Closes an issue (or reopens it)', [REPO, NUMBER, SEL('state', 'Set it to', [['closed', 'Closed'], ['open', 'Open again']])], (a, c, p) => gh(a, c, `/repos/${repo(p)}/issues/${q(need(p.number, 'the number'))}`, { method: 'PATCH', body: { state: p.state || 'closed' } }).then(b => ({ number: b.number, state: b.state, url: b.html_url })));
A('github', 'labels', 'Add labels', 'Adds labels to an issue or pull request', [REPO, NUMBER, F('labels', 'Labels', 'bug, urgent')], (a, c, p) => gh(a, c, `/repos/${repo(p)}/issues/${q(need(p.number, 'the number'))}/labels`, { method: 'POST', body: { labels: list(need(p.labels, 'the labels')) } }), { list: true });
A('github', 'assign', 'Assign people', 'Assigns people to an issue or pull request', [REPO, NUMBER, F('assignees', 'Usernames', 'octocat, ada')], (a, c, p) => gh(a, c, `/repos/${repo(p)}/issues/${q(need(p.number, 'the number'))}/assignees`, { method: 'POST', body: { assignees: list(need(p.assignees, 'the usernames')) } }).then(b => ({ number: b.number, assignees: (b.assignees || []).map(x => x.login) })));
A('github', 'listPulls', 'List pull requests', 'Lists a repository’s pull requests', [REPO, SEL('state', 'Which', [['open', 'Open'], ['closed', 'Closed'], ['all', 'All']]), LIMIT], (a, c, p) => gh(a, c, `/repos/${repo(p)}/pulls?state=${q(p.state || 'open')}&per_page=${lim(p)}`).then(l => l.map(x => ({ number: x.number, title: x.title, user: x.user?.login, state: x.state, draft: x.draft, head: x.head?.ref, base: x.base?.ref, url: x.html_url, createdAt: x.created_at }))), { list: true });
A('github', 'createPull', 'Open a pull request', 'Opens a pull request from one branch into another', [REPO, F('title', 'Title', 'Add dark mode'), F('head', 'From branch', 'feature/dark-mode'), F('base', 'Into branch', 'main', { d: 'main' }), TA('body', 'Description', '')], (a, c, p) => gh(a, c, `/repos/${repo(p)}/pulls`, { method: 'POST', body: { title: need(p.title, 'the title'), head: need(p.head, 'the branch'), base: p.base || 'main', body: p.body || '' } }).then(b => ({ number: b.number, url: b.html_url })));
A('github', 'mergePull', 'Merge a pull request', 'Merges a pull request (merge, squash or rebase)', [REPO, F('number', 'PR number', '{{ $json.number }}'), SEL('method', 'How', [['merge', 'Merge commit'], ['squash', 'Squash'], ['rebase', 'Rebase']])], (a, c, p) => gh(a, c, `/repos/${repo(p)}/pulls/${q(need(p.number, 'the number'))}/merge`, { method: 'PUT', body: { merge_method: p.method || 'merge' } }));
A('github', 'createRelease', 'Publish a release', 'Creates a release with a tag and notes', [REPO, F('tag', 'Tag', 'v1.2.0'), F('name', 'Title', 'Version 1.2'), TA('body', 'Notes', ''), SEL('draft', 'As', [['false', 'Published'], ['true', 'Draft']])], (a, c, p) => gh(a, c, `/repos/${repo(p)}/releases`, { method: 'POST', body: { tag_name: need(p.tag, 'the tag'), name: p.name || p.tag, body: p.body || '', draft: p.draft === 'true', generate_release_notes: !p.body } }).then(b => ({ id: b.id, url: b.html_url, tag: b.tag_name })));
A('github', 'listReleases', 'List releases', 'Lists a repository’s releases, newest first', [REPO, LIMIT], (a, c, p) => gh(a, c, `/repos/${repo(p)}/releases?per_page=${lim(p)}`).then(l => l.map(x => ({ tag: x.tag_name, name: x.name, url: x.html_url, publishedAt: x.published_at, draft: x.draft, prerelease: x.prerelease }))), { list: true });
A('github', 'listCommits', 'List commits', 'Lists the latest commits on a branch', [REPO, F('branch', 'Branch (blank: the default)', 'main'), LIMIT], (a, c, p) => gh(a, c, `/repos/${repo(p)}/commits?per_page=${lim(p)}${p.branch ? `&sha=${q(p.branch)}` : ''}`).then(l => l.map(x => ({ sha: x.sha, message: x.commit?.message, author: x.commit?.author?.name, date: x.commit?.author?.date, url: x.html_url }))), { list: true });
A('github', 'getFile', 'Read a file', 'Reads a file from a repository', [REPO, F('path', 'File path', 'README.md'), F('ref', 'Branch (blank: the default)', '')], async (a, c, p) => { const b = await gh(a, c, `/repos/${repo(p)}/contents/${String(need(p.path, 'the path')).split('/').map(q).join('/')}${p.ref ? `?ref=${q(p.ref)}` : ''}`); return { path: b.path, sha: b.sha, size: b.size, url: b.html_url, content: b.encoding === 'base64' ? Buffer.from(b.content || '', 'base64').toString('utf8') : b.content }; });
A('github', 'putFile', 'Write a file', 'Creates or updates a file in a repository, as a commit', [REPO, F('path', 'File path', 'data/report.md'), TA('content', 'Content', '{{ $json.text }}'), F('message', 'Commit message', 'Update report'), F('branch', 'Branch (blank: the default)', '')], async (a, c, p) => {
  const path = String(need(p.path, 'the path')).split('/').map(q).join('/'), base = `/repos/${repo(p)}/contents/${path}`;
  let sha;
  const r = await api(a, `https://api.github.com${base}${p.branch ? `?ref=${q(p.branch)}` : ''}`, { bearer: c.token, headers: { accept: 'application/vnd.github+json', 'user-agent': 'Workline' } });
  if (r.ok && r.body?.sha) sha = r.body.sha;
  const b = await gh(a, c, base, { method: 'PUT', body: { message: p.message || `Update ${p.path}`, content: Buffer.from(String(p.content ?? '')).toString('base64'), ...(sha ? { sha } : {}), ...(p.branch ? { branch: p.branch } : {}) } });
  return { path: b.content?.path, sha: b.content?.sha, commit: b.commit?.sha, url: b.content?.html_url, created: !sha };
});
A('github', 'gist', 'Create a gist', 'Saves text as a GitHub gist and gives its link', [F('filename', 'File name', 'notes.md'), TA('content', 'Content', '{{ $json.text }}'), F('description', 'Description', ''), SEL('public', 'Visibility', [['false', 'Secret'], ['true', 'Public']])], (a, c, p) => gh(a, c, '/gists', { method: 'POST', body: { description: p.description || '', public: p.public === 'true', files: { [p.filename || 'file.txt']: { content: String(need(p.content, 'the content')) } } } }).then(b => ({ id: b.id, url: b.html_url })));
