/* ================= Linear ================= */
const lin = async (args, c, query, variables) => { const b = failIfBad(await api(args, 'https://api.linear.app/graphql', { method: 'POST', headers: { authorization: c.apiKey }, body: { query, variables } }), 'Linear'); if (b.errors?.length) throw new FlowError(`Linear: ${b.errors[0].message}`, 'service'); return b.data; };
A('linear', 'comment', 'Comment on an issue', 'Adds a comment to a Linear issue (by its id or key, like ENG-12)', [F('issueId', 'Issue', 'ENG-12'), TA('body', 'Comment', '')], (a, c, p) => lin(a, c, 'mutation($i: CommentCreateInput!) { commentCreate(input: $i) { success comment { id url } } }', { i: { issueId: need(p.issueId, 'the issue'), body: need(p.body, 'the comment') } }).then(d => d.commentCreate.comment));
A('linear', 'teams', 'List teams', 'Lists the teams in your Linear workspace (with their ids)', [], (a, c) => lin(a, c, '{ teams { nodes { id name key } } }').then(d => d.teams.nodes), { list: true });
A('linear', 'projects', 'List projects', 'Lists Linear projects', [LIMIT], (a, c, p) => lin(a, c, 'query($n: Int) { projects(first: $n) { nodes { id name state progress url } } }', { n: lim(p) }).then(d => d.projects.nodes), { list: true });
A('linear', 'update', 'Update an issue', 'Changes an issue’s title, priority or state', [F('issueId', 'Issue', 'ENG-12'), F('title', 'Title (blank: keep)', ''), SEL('priority', 'Priority', [['', 'Keep'], ['1', 'Urgent'], ['2', 'High'], ['3', 'Medium'], ['4', 'Low'], ['0', 'None']], ''), F('stateId', 'State id (blank: keep)', '')], (a, c, p) => lin(a, c, 'mutation($id: String!, $i: IssueUpdateInput!) { issueUpdate(id: $id, input: $i) { success issue { id identifier title url } } }', { id: need(p.issueId, 'the issue'), i: { ...(p.title ? { title: p.title } : {}), ...(p.priority !== '' && p.priority != null ? { priority: Number(p.priority) } : {}), ...(p.stateId ? { stateId: p.stateId } : {}) } }).then(d => d.issueUpdate.issue));

/* ================= Zendesk ================= */
const zd = async (args, c, path, init = {}) => failIfBad(await api(args, `https://${strip(c.subdomain).replace(/^https?:\/\//, '').replace(/\.zendesk\.com$/, '')}.zendesk.com/api/v2${path}`, { ...init, basic: `${c.email}/token:${c.apiToken}` }), 'Zendesk');
const TICKET = F('ticketId', 'Ticket id', '{{ $json.id }}');
A('zendesk', 'reply', 'Reply to a ticket', 'Adds a public reply (or an internal note) to a ticket', [TICKET, TA('body', 'Reply', ''), SEL('public', 'As', [['true', 'A public reply'], ['false', 'An internal note']])], (a, c, p) => zd(a, c, `/tickets/${q(need(p.ticketId, 'the ticket'))}.json`, { method: 'PUT', body: { ticket: { comment: { body: need(p.body, 'the reply'), public: p.public !== 'false' } } } }).then(b => ({ id: b.ticket?.id, status: b.ticket?.status })));
A('zendesk', 'status', 'Set ticket status', 'Sets a ticket to open, pending, solved…', [TICKET, SEL('status', 'Status', [['solved', 'Solved'], ['open', 'Open'], ['pending', 'Pending'], ['hold', 'On hold'], ['closed', 'Closed']])], (a, c, p) => zd(a, c, `/tickets/${q(need(p.ticketId, 'the ticket'))}.json`, { method: 'PUT', body: { ticket: { status: p.status || 'solved' } } }).then(b => ({ id: b.ticket?.id, status: b.ticket?.status })));
A('zendesk', 'getTicket', 'Get a ticket', 'Reads one ticket', [TICKET], (a, c, p) => zd(a, c, `/tickets/${q(need(p.ticketId, 'the ticket'))}.json`).then(b => b.ticket));
A('zendesk', 'createUser', 'Create a user', 'Adds an end user (customer)', [F('name', 'Name', '{{ $json.name }}'), F('email', 'Email', '{{ $json.email }}')], (a, c, p) => zd(a, c, '/users/create_or_update.json', { method: 'POST', body: { user: { name: need(p.name, 'the name'), email: need(p.email, 'the email') } } }).then(b => ({ id: b.user?.id, email: b.user?.email })));
A('zendesk', 'search', 'Search', 'Searches tickets, users and organizations', [F('query', 'Search', 'type:ticket status:open'), LIMIT], (a, c, p) => zd(a, c, `/search.json?query=${q(need(p.query, 'the search'))}&per_page=${lim(p)}`).then(b => b.results || []), { list: true });

/* ================= PagerDuty ================= */
const pdEvent = (action, label, note) => A('pagerduty', action, label, note, [F('dedupKey', 'Incident key', '{{ $json.dedup_key }}')], (a, c, p) => api(a, 'https://events.pagerduty.com/v2/enqueue', { method: 'POST', body: { routing_key: c.routingKey, event_action: action, dedup_key: need(p.dedupKey, 'the incident key') } }).then(r => failIfBad(r, 'PagerDuty')));
pdEvent('acknowledge', 'Acknowledge an incident', 'Marks an alert as seen, so it stops paging');
pdEvent('resolve', 'Resolve an incident', 'Closes an alert');

/* ================= Stripe ================= */
const st = async (args, c, path, form, method) => failIfBad(await api(args, `https://api.stripe.com/v1${path}`, { method: method || (form ? 'POST' : 'GET'), basic: `${c.secretKey}:`, ...(form ? { form } : {}) }), 'Stripe');
const AMOUNT = F('amount', 'Amount (in rupees, dollars…)', '499');
const CUR = F('currency', 'Currency', 'inr', { d: 'inr' });
const cents = v => { const n = Number(String(v).replace(/[,₹$€£\s]/g, '')); if (!Number.isFinite(n) || n <= 0) throw new FlowError('The amount must be a number above 0.', 'bad_param'); return String(Math.round(n * 100)); };
const CUSTOMER = F('customer', 'Customer id', 'cus_…');
A('stripe', 'checkout', 'Create a checkout link', 'Makes a Stripe Checkout page for a one-off payment and gives its link', [F('name', 'Product name', 'Pro plan'), AMOUNT, CUR, NUM('quantity', 'Quantity', 1), F('successUrl', 'After paying, go to', 'https://example.com/thanks'), F('email', 'Customer email (optional)', '{{ $json.email }}')], (a, c, p) => st(a, c, '/checkout/sessions', { mode: 'payment', 'line_items[0][price_data][currency]': (p.currency || 'inr').toLowerCase(), 'line_items[0][price_data][product_data][name]': need(p.name, 'the product name'), 'line_items[0][price_data][unit_amount]': cents(need(p.amount, 'the amount')), 'line_items[0][quantity]': String(p.quantity || 1), success_url: need(p.successUrl, 'where to go after paying'), ...(p.email ? { customer_email: p.email } : {}) }).then(b => ({ id: b.id, url: b.url, amount: b.amount_total, currency: b.currency })));
A('stripe', 'paymentLink', 'Create a payment link', 'Makes a reusable payment link for a price', [F('price', 'Price id', 'price_…'), NUM('quantity', 'Quantity', 1)], (a, c, p) => st(a, c, '/payment_links', { 'line_items[0][price]': need(p.price, 'the price id'), 'line_items[0][quantity]': String(p.quantity || 1) }).then(b => ({ id: b.id, url: b.url })));
A('stripe', 'product', 'Create a product with a price', 'Creates a product and its price (one-off or monthly/yearly)', [F('name', 'Name', 'Pro plan'), TA('description', 'Description', ''), AMOUNT, CUR, SEL('interval', 'Billing', [['', 'One-off'], ['month', 'Monthly'], ['year', 'Yearly']], '')], async (a, c, p) => { const prod = await st(a, c, '/products', { name: need(p.name, 'the name'), ...(p.description ? { description: p.description } : {}) }); const price = await st(a, c, '/prices', { product: prod.id, unit_amount: cents(need(p.amount, 'the amount')), currency: (p.currency || 'inr').toLowerCase(), ...(p.interval ? { 'recurring[interval]': p.interval } : {}) }); return { product: prod.id, price: price.id, name: prod.name }; });
A('stripe', 'products', 'List products', 'Lists your Stripe products', [LIMIT], (a, c, p) => st(a, c, `/products?limit=${lim(p)}`).then(b => b.data), { list: true });
A('stripe', 'invoice', 'Send an invoice', 'Bills a customer: adds a line, then creates, finalises and emails the invoice', [CUSTOMER, F('description', 'For', 'Consulting, March'), AMOUNT, CUR, NUM('days', 'Due in days', 7)], async (a, c, p) => {
  const inv = await st(a, c, '/invoices', { customer: need(p.customer, 'the customer'), collection_method: 'send_invoice', days_until_due: String(p.days || 7), auto_advance: 'false' });
  await st(a, c, '/invoiceitems', { customer: p.customer, invoice: inv.id, amount: cents(need(p.amount, 'the amount')), currency: (p.currency || 'inr').toLowerCase(), description: p.description || 'Invoice' });
  await st(a, c, `/invoices/${inv.id}/finalize`, {});
  const sent = await st(a, c, `/invoices/${inv.id}/send`, {});
  return { id: sent.id, number: sent.number, url: sent.hosted_invoice_url, pdf: sent.invoice_pdf, total: sent.total, status: sent.status };
});
A('stripe', 'invoices', 'List invoices', 'Lists invoices (all, or one customer’s)', [F('customer', 'Customer id (optional)', ''), SEL('status', 'Which', [['', 'All'], ['open', 'Open'], ['paid', 'Paid'], ['draft', 'Draft'], ['uncollectible', 'Uncollectible']], ''), LIMIT], (a, c, p) => st(a, c, `/invoices?limit=${lim(p)}${p.customer ? `&customer=${q(p.customer)}` : ''}${p.status ? `&status=${q(p.status)}` : ''}`).then(b => b.data.map(x => ({ id: x.id, number: x.number, customer: x.customer, email: x.customer_email, total: x.total, currency: x.currency, status: x.status, url: x.hosted_invoice_url, created: new Date(x.created * 1000).toISOString() }))), { list: true });
A('stripe', 'refund', 'Refund a payment', 'Refunds a payment in full, or part of it', [F('payment', 'Payment intent id', 'pi_…'), F('amount', 'Amount (blank: all of it)', '')], (a, c, p) => st(a, c, '/refunds', { payment_intent: need(p.payment, 'the payment'), ...(p.amount ? { amount: cents(p.amount) } : {}) }).then(b => ({ id: b.id, amount: b.amount, status: b.status })));
A('stripe', 'subscriptions', 'List subscriptions', 'Lists subscriptions (active ones by default)', [SEL('status', 'Which', [['active', 'Active'], ['all', 'All'], ['past_due', 'Past due'], ['canceled', 'Cancelled'], ['trialing', 'Trialing']]), LIMIT], (a, c, p) => st(a, c, `/subscriptions?limit=${lim(p)}&status=${q(p.status || 'active')}`).then(b => b.data.map(x => ({ id: x.id, customer: x.customer, status: x.status, plan: x.items?.data?.[0]?.price?.id, amount: x.items?.data?.[0]?.price?.unit_amount, interval: x.items?.data?.[0]?.price?.recurring?.interval, renews: x.current_period_end ? new Date(x.current_period_end * 1000).toISOString() : x.items?.data?.[0]?.current_period_end ? new Date(x.items.data[0].current_period_end * 1000).toISOString() : null }))), { list: true });
A('stripe', 'cancel', 'Cancel a subscription', 'Cancels a subscription now, or at the end of the period', [F('subscription', 'Subscription id', 'sub_…'), SEL('when', 'When', [['end', 'At the end of the period'], ['now', 'Right now']])], (a, c, p) => (p.when === 'now' ? st(a, c, `/subscriptions/${q(need(p.subscription, 'the subscription'))}`, undefined, 'DELETE') : st(a, c, `/subscriptions/${q(need(p.subscription, 'the subscription'))}`, { cancel_at_period_end: 'true' })).then(b => ({ id: b.id, status: b.status, endsAtPeriodEnd: b.cancel_at_period_end })));
A('stripe', 'customer', 'Get a customer', 'Reads one customer', [CUSTOMER], (a, c, p) => st(a, c, `/customers/${q(need(p.customer, 'the customer'))}`).then(b => ({ id: b.id, email: b.email, name: b.name, phone: b.phone, balance: b.balance, created: new Date(b.created * 1000).toISOString() })));
A('stripe', 'findCustomer', 'Find a customer by email', 'Finds customers with an email address', [F('email', 'Email', '{{ $json.email }}')], (a, c, p) => st(a, c, `/customers/search?query=${q(`email:'${String(need(p.email, 'the email')).replace(/'/g, "\\'")}'`)}`).then(b => b.data.map(x => ({ id: x.id, email: x.email, name: x.name }))), { list: true });
A('stripe', 'coupon', 'Create a coupon', 'Makes a percent-off coupon and a promotion code people can type', [NUM('percent', 'Percent off', 20), F('code', 'Code', 'DIWALI20'), SEL('duration', 'Applies', [['once', 'Once'], ['forever', 'Forever']])], async (a, c, p) => { const cp = await st(a, c, '/coupons', { percent_off: String(p.percent || 10), duration: p.duration || 'once' }); const pc = p.code ? await st(a, c, '/promotion_codes', { coupon: cp.id, code: p.code }) : null; return { coupon: cp.id, code: pc?.code || null, percentOff: cp.percent_off }; });
A('stripe', 'charges', 'List payments received', 'Lists recent successful charges', [LIMIT], (a, c, p) => st(a, c, `/charges?limit=${lim(p)}`).then(b => b.data.map(x => ({ id: x.id, amount: x.amount / 100, currency: x.currency, paid: x.paid, refunded: x.refunded, email: x.billing_details?.email || x.receipt_email, description: x.description, receipt: x.receipt_url, created: new Date(x.created * 1000).toISOString() }))), { list: true });

