/* ================= Slack ================= */
const sl = async (args, c, method, body, get) => {
  if (!c.token) throw new FlowError('This needs a Slack bot token (xoxb-…) in the credential.', 'credential');
  const r = await api(args, `https://slack.com/api/${method}${get ? `?${new URLSearchParams(body)}` : ''}`, { method: get ? 'GET' : 'POST', bearer: c.token, ...(get ? {} : { body, headers: { 'content-type': 'application/json; charset=utf-8' } }) });
  const b = failIfBad(r, 'Slack');
  if (!b.ok) throw new FlowError(`Slack: ${b.error}`, 'service');
  return b;
};
const CHANNEL = F('channel', 'Channel', '#general  or  C0123…');
