A('pub', 'dns', 'DNS lookup', 'Looks up a domain’s DNS records (A, MX, TXT…)', [F('domain', 'Domain', 'example.com'), SEL('type', 'Record', [['A', 'A (IPv4)'], ['AAAA', 'AAAA (IPv6)'], ['MX', 'MX (mail)'], ['TXT', 'TXT'], ['CNAME', 'CNAME'], ['NS', 'NS'], ['CAA', 'CAA']])], (a, c, p) => get(a, `https://dns.google/resolve?name=${q(need(p.domain, 'the domain'))}&type=${q(p.type || 'A')}`, 'Google DNS').then(b => (b.Answer || []).map(x => ({ name: x.name, type: p.type || 'A', ttl: x.TTL, value: x.data }))), { list: true, icon: 'globe' });
A('pub', 'up', 'Is the site up?', 'Checks a website: its status code and how fast it answered', [F('url', 'Link', 'https://example.com')], async (a, c, p) => { const url = String(need(p.url, 'the link')); const t = Date.now(); try { const r = await api(a, /^https?:\/\//.test(url) ? url : `https://${url}`, { headers: { accept: '*/*' }, timeout: 15_000 }); return { url, up: r.status < 400, status: r.status, ms: Date.now() - t }; } catch (e) { return { url, up: false, status: null, ms: Date.now() - t, error: e.message }; } }, { icon: 'eye' });
A('pub', 'xkcd', 'xkcd comic', 'The latest xkcd comic (or a numbered one)', [F('number', 'Number (blank: the latest)', '')], (a, c, p) => get(a, `https://xkcd.com/${p.number ? `${q(p.number)}/` : ''}info.0.json`, 'xkcd').then(b => ({ number: b.num, title: b.safe_title, image: b.img, alt: b.alt, date: `${b.year}-${String(b.month).padStart(2, '0')}-${String(b.day).padStart(2, '0')}`, url: `https://xkcd.com/${b.num}/` })), { icon: 'image' });
A('pub', 'apod', 'NASA picture of the day', 'NASA’s Astronomy Picture of the Day, with its explanation', [F('date', 'Date (blank: today)', ''), F('apiKey', 'NASA API key (blank: the shared demo key)', '')], (a, c, p) => get(a, `https://api.nasa.gov/planetary/apod?api_key=${q(p.apiKey || 'DEMO_KEY')}${p.date ? `&date=${q(p.date)}` : ''}`, 'NASA').then(b => ({ title: b.title, date: b.date, explanation: b.explanation, image: b.hdurl || b.url, type: b.media_type, credit: b.copyright || null })), { icon: 'star' });
A('pub', 'joke', 'A joke', 'A random clean joke (setup and punchline)', [], a => get(a, 'https://official-joke-api.appspot.com/random_joke', 'Joke API').then(b => ({ setup: b.setup, punchline: b.punchline, type: b.type })), { icon: 'chat' });
A('pub', 'advice', 'A piece of advice', 'A random short piece of advice', [], a => get(a, 'https://api.adviceslip.com/advice', 'Advice Slip').then(b => (typeof b === 'string' ? JSON.parse(b) : b)).then(b => ({ advice: b.slip?.advice, id: b.slip?.id })), { icon: 'chat' });
A('pub', 'universities', 'Find universities', 'Lists universities in a country, or by name', [F('country', 'Country', 'India'), F('name', 'Name has', '')], (a, c, p) => get(a, `http://universities.hipolabs.com/search?country=${q(p.country || '')}${p.name ? `&name=${q(p.name)}` : ''}`, 'Universities').then(l => l.slice(0, 200).map(u => ({ name: u.name, country: u.country, state: u['state-province'], website: u.web_pages?.[0], domain: u.domains?.[0] }))), { list: true, icon: 'text' });
